import{_ as n,C as a,o as i,c as o,E as t,a9 as c}from"./chunks/framework.asyjyako.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PerfChecker.jl","text":"Performance checks from your Julia tests","tagline":"Run one item, inspect its measurements, and compare results with an explicit performance budget.","image":{"src":"/assets/perfchecker.svg","alt":"PerfChecker performance pulse"},"actions":[{"theme":"brand","text":"Start measuring","link":"/guide/first-check"},{"theme":"alt","text":"Use VS Code","link":"/interfaces/vscode"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/Mirage-Interactive-Fr/PerfChecker.jl"}]},"features":[{"icon":"⚗️","title":"Reuse existing tests","details":"Discover ordinary TestItemRunner items. Share them between correctness and performance, or separate them with tags.","link":"/test-items"},{"icon":"↔️","title":"Compare measured results","details":"Define a baseline, matching measurement scope and regression limits before deciding whether a change passes.","link":"/tutorials/comparisons"},{"icon":"🔥","title":"Investigate a regression","details":"Inspect Julia timings, allocations and profiles, then choose diagnostics for the target and its native dependencies.","link":"/native-profiling"},{"icon":"▦","title":"Run one item in VS Code","details":"Discover items in the Testing view, select a check and retain its measurements and source identity.","link":"/interfaces/vscode"},{"icon":"✓","title":"Automate the same checks","details":"Use scripts and CI with JSON, Markdown and JUnit reports. Keep execution, correctness and regression verdicts separate.","link":"/tutorials/ci"},{"icon":"⌘","title":"Reopen saved evidence","details":"Read portable run bundles in Web Studio, Pluto, plots or reports without repeating the measurement.","link":"/reference/run-bundles"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),l={name:"index.md"};function d(p,e,u,h,m,f){const s=a("MaintainerLink"),r=a("HomeMeasurements");return i(),o("div",null,[t(s),t(r),e[0]||(e[0]=c(`<p><a href="./tutorials/quick-tour">Read the short Bibliography tutorial</a> or <a href="./interfaces/visualization">explore the interactive plots</a>.</p><p>For a larger runnable example, <a href="./real-packages/">compare DataStructures and Oxygen across releases</a>, then reuse their measurements in the terminal, notebooks and graphical interfaces.</p><h2 id="Performance-checks-as-software-tests" tabindex="-1">Performance checks as software tests <a class="header-anchor" href="#Performance-checks-as-software-tests" aria-label="Permalink to &quot;Performance checks as software tests {#Performance-checks-as-software-tests}&quot;">​</a></h2><p>PerfChecker treats performance as a versioned contract attached to a <strong>business feature</strong>. <code>import_bibtex</code>, <code>solve_model</code>, or <code>render_frame</code> is the feature; BenchmarkTools, Chairmarks, allocation tracking, profiling and network accounting are selectable ways to evaluate it. This separation keeps the suite readable and lets every interface offer the same choices.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>software suite</span></span>
<span class="line"><span>  └─ package</span></span>
<span class="line"><span>      └─ business feature</span></span>
<span class="line"><span>          ├─ check type</span></span>
<span class="line"><span>          └─ target: release | working tree | branch | tag | commit</span></span></code></pre></div><p>The controller resolves this plan, performs compatibility checks and launches bounded workers. The measured worker loads only the target package, workload and collector. Results return as a portable run bundle consumed by every UI and CI adapter.</p><h2 id="Pick-a-path" tabindex="-1">Pick a path <a class="header-anchor" href="#Pick-a-path" aria-label="Permalink to &quot;Pick a path {#Pick-a-path}&quot;">​</a></h2><div class="feature-grid"><div><strong>I maintain one package</strong>Start with <a href="/guide/first-check">your first test item</a>, then add versions and CI.</div><div><strong>I maintain a software suite</strong>Model package boundaries and version pins in <a href="/suites-and-comparisons">suites and comparisons</a>.</div><div><strong>I am investigating a regression</strong>Compare <a href="/tutorials/comparisons">releases and Git revisions</a> or <a href="/tutorials/julia-runtimes">Julia runtimes</a>.</div><div><strong>I need interactive analysis</strong>Choose <a href="/interfaces/vscode">VS Code</a>, <a href="/interfaces/web-studio">Oxygen</a>, or <a href="/interfaces/visualization">Makie</a>.</div><div><strong>I run a hosted service</strong>Review the <a href="/operations/hosted">controller, authentication and remote-agent model</a>.</div><div><strong>I build automation</strong>Consume <a href="/reference/run-bundles">run bundles</a> and <a href="/report-queries">bounded queries</a>.</div></div><h2 id="Try-a-small-example" tabindex="-1">Try a small example <a class="header-anchor" href="#Try-a-small-example" aria-label="Permalink to &quot;Try a small example {#Try-a-small-example}&quot;">​</a></h2><p>Follow the <a href="./tutorials/quick-tour">short Bibliography tutorial</a> to read a real plot, run one export check and compare nine tagged versions. You can inspect the recorded results before installing anything.</p><h2 id="Take-part" tabindex="-1">Take part <a class="header-anchor" href="#Take-part" aria-label="Permalink to &quot;Take part {#Take-part}&quot;">​</a></h2><p>PerfChecker is open source. Bug reports, examples, measurement tools and clearer documentation are all useful contributions. <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/issues" target="_blank" rel="noreferrer">Open an issue</a> or follow the <a href="./contributing/documentation">documentation contribution guide</a>.</p><p>Community contributions are welcome.</p>`,13))])}const v=n(l,[["render",d]]);export{k as __pageData,v as default};
